"""Engine DECISIONS of a scenario run, without geography or wording.

Used by tests/test_relocation.py to prove that moving the demo from Bengaluru (MG Road) to
Murthal/Sonipat changed no decision. Coordinates, titles, texts, audit detail strings, distances,
names and service ids are left out on purpose; everything the engine decides is kept.

decisions_bengaluru.json was generated by running this file against origin/main BEFORE the move
(commit 9fc7200, MG Road coordinates). Do not regenerate it to make the test pass.
Usage (from backend/): python3 tests/fixtures/decisions.py tests/fixtures/decisions_bengaluru.json
"""
import json
import os
import sys

INCIDENT_KEYS = ("id", "status", "category", "department", "severity", "escalation_level", "plan_version",
                 "report_ids", "related_incident_ids", "assigned_resource_id", "parent_incident_id",
                 "child_incident_ids", "at_risk", "created_at", "deadline", "completed_at",
                 "verification", "sla_state")
SCENARIOS = ("golden", "rootcause")


def project(c, name: str) -> dict:
    """Run scenario `name` step by step from a reset and return its decisions."""
    c.post("/sim/reset")
    steps = []
    n = 1
    while True:
        r = c.post(f"/sim/scenario/{name}", params={"step": n})
        if r.status_code != 200:
            break
        st = r.json()["state"]
        steps.append({
            "step": n,
            "now": st["now"],
            "incidents": [{k: i.get(k) for k in INCIDENT_KEYS} for i in st["incidents"]],
            "resources": [{k: x[k] for k in ("id", "department", "available", "active_incident_ids")}
                          for x in st["resources"]],
            "metrics": st["metrics"],
        })
        n += 1
    details = {}
    for inc in c.get("/incidents").json():
        d = c.get(f"/incidents/{inc['id']}").json()
        details[inc["id"]] = {
            "links": sorted([lk["id"], lk["report_id"], lk["incident_id"], lk["kind"], lk["confidence"]]
                            for lk in d["links"]),
            "evidence": [[e["kind"], e["supports_resolution"], e["signal_only"]] for e in d["evidence"]],
            "audit": [[a["event_type"], a.get("to_status"), a["actor"]] for a in d["audit"]],
            "impact": sorted([s["kind"], s["via_incident_id"]]
                             for s in c.get(f"/incidents/{inc['id']}/impact").json()["services"]),
        }
    hyps = [{k: h[k] for k in ("id", "status", "cause_incident_id", "member_ids", "confidence")}
            for h in c.get("/hypotheses").json()]
    return {"steps": steps, "details": details, "hypotheses": hyps, "metrics": c.get("/metrics").json()}


if __name__ == "__main__":
    os.environ["CONVERGE_DB_URL"] = "sqlite://"
    os.environ["CONVERGE_LLM"] = "off"
    sys.path.insert(0, os.getcwd())
    from fastapi.testclient import TestClient

    from app.main import app

    with TestClient(app) as client:
        out = {name: project(client, name) for name in SCENARIOS}
    with open(sys.argv[1], "w") as f:
        json.dump(out, f, indent=1, sort_keys=True)
    print({k: len(v["steps"]) for k, v in out.items()})
